def best(s):
 best=None
 for lab,t in [('+',seq),('-',rc)]:
  for i in range(len(t)-len(s)+1):
   mism=sum(a"'!=b for a,b in zip(s,t[i:i+len(s)]))
   if mism<=5:
    if best is None or mism<best[0]: best=(mism,lab,i)
 return best
for name in ['"'exo','endo','mix']:
 stats={'exact':0,'mm1':0,'mm2':0,'mm3':0,'mm45':0,'no':0}
 poss=[]
 for s in reads[name]:
  b=best(s)
  if b:
   m,lab,i=b; poss.append((lab,i,m,s))
   if m==0: stats['exact']+=1
   elif m==1: stats['mm1']+=1
   elif m==2: stats['mm2']+=1
   elif m==3: stats['mm3']+=1
   else: stats['mm45']+=1
  else: stats['no']+=1
 print(name, stats)
# print unassigned unique exo/endo/mix
